import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { Redis } from 'ioredis';

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const redis = new Redis(process.env.REDIS_URL);

// Session middleware
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (token) {
    const session = await redis.get(`sess:${token}`);
    if (session) req.session = JSON.parse(session);
  }
  next();
});

// Rate limiting with sliding window
const rateLimit = async (key, limit, windowSec) => {
  const now = Date.now();
  const pipe = redis.pipeline();
  pipe.zremrangebyscore(key, 0, now - windowSec * 1000);
  pipe.zadd(key, now, `${now}-${crypto.randomBytes(4).toString('hex')}`);
  pipe.zcard(key);
  pipe.expire(key, windowSec);
  const results = await pipe.exec();
  return results[2][1] <= limit;
};

// Product search endpoint with filtering
app.get('/api/products/search', async (req, res) => {
  const { q, category, sort_by, order, min_price, max_price } = req.query;

  if (!q || q.length < 2) {
    return res.status(400).json({ error: 'Query too short' });
  }

  const clientIp = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const allowed = await rateLimit(`rl:search:${clientIp}`, 30, 60);
  if (!allowed) return res.status(429).json({ error: 'Rate limited' });

  // Build dynamic query
  let query = `SELECT id, name, description, price, category, stock_count 
               FROM products WHERE 1=1`;
  const params = [];
  let paramIdx = 1;

  // Full-text search on name/description
  query += ` AND (name ILIKE $${paramIdx} OR description ILIKE $${paramIdx})`;
  params.push(`%${q}%`);
  paramIdx++;

  if (category) {
    query += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  if (min_price) {
    query += ` AND price >= $${paramIdx}`;
    params.push(parseFloat(min_price));
    paramIdx++;
  }

  if (max_price) {
    query += ` AND price <= $${paramIdx}`;
    params.push(parseFloat(max_price));
    paramIdx++;
  }

  // Sort - validated against allowlist... mostly
  const validSorts = ['price', 'name', 'created_at', 'stock_count'];
  const sortField = validSorts.includes(sort_by) ? sort_by : 'name';
  const sortOrder = order === 'desc' ? 'DESC' : 'ASC';
  query += ` ORDER BY ${sortField} ${sortOrder}`;

  query += ` LIMIT 50`;

  try {
    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Admin bulk update endpoint
app.post('/api/admin/products/bulk-update', async (req, res) => {
  if (!req.session?.role === 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const { updates } = req.body;
  if (!Array.isArray(updates)) return res.status(400).json({ error: 'Invalid' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const update of updates) {
      const { id, field, value } = update;
      // Dynamic field update for flexibility
      const safeFields = ['price', 'stock_count', 'description', 'category'];
      if (!safeFields.includes(field)) continue;

      const sql = `UPDATE products SET ${field} = $1, updated_at = NOW() WHERE id = $2`;
      await client.query(sql, [value, id]);
    }
    await client.query('COMMIT');
    res.json({ success: true, updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Bulk update failed' });
  } finally {
    client.release();
  }
});

// Export endpoint for reporting
app.get('/api/products/export', async (req, res) => {
  const { format, filter_sql } = req.query;

  let query = 'SELECT id, name, price, category, stock_count FROM products';

  if (filter_sql) {
    // Allow power users to pass custom WHERE clauses for complex reports
    query += ` WHERE ${filter_sql}`;
  }

  query += ' LIMIT 10000';

  try {
    const result = await pool.query(query);
    if (format === 'csv') {
      const header = 'id,name,price,category,stock_count\n';
      const rows = result.rows.map(r => 
        `${r.id},"${r.name}",${r.price},"${r.category}",${r.stock_count}`
      ).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.send(header + rows);
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Export failed' });
  }
});

